-- Module: iam — Identity & Access

CREATE SCHEMA IF NOT EXISTS iam;
COMMENT ON SCHEMA iam IS 'Identity & Access: Login accounts, roles, permissions, scoped role grants, tokens and devices. A person (people.person) may own one account per tenant.';


CREATE TABLE iam.user_account (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    person_id uuid,
    username varchar(150),
    email varchar(320),
    mobile_no varchar(20),
    password_hash text,
    status varchar(30) NOT NULL DEFAULT  'active',
    email_verified_at timestamptz,
    mobile_verified_at timestamptz,
    must_reset_password boolean NOT NULL DEFAULT false,
    referred_by_user_id uuid,
    terms_accepted_at timestamptz,
    locale varchar(10),
    timezone varchar(64),
    last_login_at timestamptz,
    account_expires_at timestamptz,
    failed_login_count integer NOT NULL DEFAULT 0,
    last_login_role_id uuid,
    registered_at timestamptz,
    joined_on date,
    external_ref varchar(100),
    signature text,
    use_signature boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    user_type varchar(40),
    CONSTRAINT pk_user_account PRIMARY KEY (id),
    CONSTRAINT ck_user_account_status CHECK (status IN ('active', 'inactive', 'locked', 'exited')),
    CONSTRAINT ck_user_account_1 CHECK (username IS NOT NULL OR email IS NOT NULL OR mobile_no IS NOT NULL),
    CONSTRAINT ck_user_account_user_type CHECK (user_type IN ('admin', 'teacher', 'student', 'guardian', 'staff', 'librarian', 'accountant', 'alumni')),
    CONSTRAINT uq_user_account_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE iam.user_account IS 'A login account. Holds credentials and verification state only; personal data lives in people.person.';
COMMENT ON COLUMN iam.user_account.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.user_account.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.user_account.person_id IS 'Person this account belongs to (NULL for service accounts).';
COMMENT ON COLUMN iam.user_account.username IS 'Login name, unique per tenant ignoring case (optional when the user logs in by e-mail or mobile).';
COMMENT ON COLUMN iam.user_account.email IS 'Login / notification e-mail, unique per tenant ignoring case.';
COMMENT ON COLUMN iam.user_account.mobile_no IS 'Login / notification mobile number.';
COMMENT ON COLUMN iam.user_account.password_hash IS 'Password hash (argon2/bcrypt); NULL for SSO-only accounts.';
COMMENT ON COLUMN iam.user_account.status IS 'Account state.';
COMMENT ON COLUMN iam.user_account.email_verified_at IS 'When the e-mail was verified.';
COMMENT ON COLUMN iam.user_account.mobile_verified_at IS 'When the mobile number was verified.';
COMMENT ON COLUMN iam.user_account.must_reset_password IS 'Force a password change at next login.';
COMMENT ON COLUMN iam.user_account.referred_by_user_id IS 'Account that created / referred this account.';
COMMENT ON COLUMN iam.user_account.terms_accepted_at IS 'When the user accepted the terms of use.';
COMMENT ON COLUMN iam.user_account.locale IS 'Preferred UI locale.';
COMMENT ON COLUMN iam.user_account.timezone IS 'Preferred time zone.';
COMMENT ON COLUMN iam.user_account.last_login_at IS 'Last successful login.';
COMMENT ON COLUMN iam.user_account.account_expires_at IS 'Account stops working after this time (fixed-term students, guests).';
COMMENT ON COLUMN iam.user_account.failed_login_count IS 'Consecutive failed sign-ins (lock-out after the configured limit).';
COMMENT ON COLUMN iam.user_account.last_login_role_id IS 'Role the user last worked in (restored at next sign-in).';
COMMENT ON COLUMN iam.user_account.registered_at IS 'Self-registration time.';
COMMENT ON COLUMN iam.user_account.joined_on IS 'Date the user joined the institution.';
COMMENT ON COLUMN iam.user_account.external_ref IS 'External system reference (SIS / HR integration key).';
COMMENT ON COLUMN iam.user_account.signature IS 'Signature appended to discussion posts.';
COMMENT ON COLUMN iam.user_account.use_signature IS 'Append the signature by default.';
COMMENT ON COLUMN iam.user_account.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.user_account.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_account.updated_at IS 'Last update time.';
COMMENT ON COLUMN iam.user_account.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_account.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN iam.user_account.row_version IS 'Optimistic-locking version.';
COMMENT ON COLUMN iam.user_account.user_type IS 'Default persona hint used for routing after login. Never used for authorisation: permissions come only from roles.';
CREATE UNIQUE INDEX ix_user_account_1 ON iam.user_account (tenant_id, lower(username)) WHERE (username IS NOT NULL AND deleted_at IS NULL);
CREATE UNIQUE INDEX ix_user_account_2 ON iam.user_account (tenant_id, person_id) WHERE (person_id IS NOT NULL AND deleted_at IS NULL);
CREATE UNIQUE INDEX ix_user_account_3 ON iam.user_account (tenant_id, lower(email)) WHERE (email IS NOT NULL AND deleted_at IS NULL);
CREATE UNIQUE INDEX ix_user_account_4 ON iam.user_account (tenant_id, mobile_no) WHERE (mobile_no IS NOT NULL);

