    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_user_session PRIMARY KEY (id),
    CONSTRAINT uq_user_session_1 UNIQUE (session_ref)
);
COMMENT ON TABLE iam.user_session IS 'Signed-in session of a user on a web browser or mobile device.';
COMMENT ON COLUMN iam.user_session.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.user_session.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.user_session.user_id IS 'User.';
COMMENT ON COLUMN iam.user_session.session_ref IS 'External session identifier (hashed).';
COMMENT ON COLUMN iam.user_session.device_id IS 'Device used.';
COMMENT ON COLUMN iam.user_session.ip_address IS 'Client IP address.';
COMMENT ON COLUMN iam.user_session.user_agent IS 'User agent.';
COMMENT ON COLUMN iam.user_session.started_at IS 'Sign-in time.';
COMMENT ON COLUMN iam.user_session.last_seen_at IS 'Last activity.';
COMMENT ON COLUMN iam.user_session.ended_at IS 'Sign-out / expiry time.';
COMMENT ON COLUMN iam.user_session.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.user_session.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_session.updated_at IS 'Last update time.';
COMMENT ON COLUMN iam.user_session.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.user_session.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN iam.user_session.row_version IS 'Optimistic-locking version.';

