-- === P0-04 / P1-30 / E34: per-tenant roles, MFA, imported credentials ===

CREATE TABLE iam.mfa_credential (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    credential_type varchar(20) NOT NULL,
    label varchar(100),
    secret_enc text NOT NULL,
    verified_at timestamptz,
    last_used_at timestamptz,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_mfa_credential PRIMARY KEY (id),
    CONSTRAINT ck_mfa_credential_type CHECK (credential_type IN ('totp', 'sms', 'email', 'recovery_codes'))
);
COMMENT ON TABLE iam.mfa_credential IS 'Second-factor credential enrolled by a user (TOTP app, SMS/email OTP target, recovery codes).';
COMMENT ON COLUMN iam.mfa_credential.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.mfa_credential.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.mfa_credential.user_id IS 'Account the credential belongs to.';
COMMENT ON COLUMN iam.mfa_credential.credential_type IS 'totp / sms / email / recovery_codes.';
COMMENT ON COLUMN iam.mfa_credential.label IS 'User-facing label (phone tail, device name).';
COMMENT ON COLUMN iam.mfa_credential.secret_enc IS 'Shared secret / target (application-encrypted envelope; write-only through the API).';
COMMENT ON COLUMN iam.mfa_credential.verified_at IS 'When enrollment was proven with a valid code; unverified credentials are not usable.';
COMMENT ON COLUMN iam.mfa_credential.last_used_at IS 'Last successful use.';
COMMENT ON COLUMN iam.mfa_credential.is_active IS 'Whether usable at sign-in.';
COMMENT ON COLUMN iam.mfa_credential.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.mfa_credential.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.mfa_credential.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN iam.mfa_credential.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN iam.mfa_credential.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN iam.mfa_credential.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';

CREATE TABLE iam.legacy_credential (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    algorithm varchar(30) NOT NULL,
    password_hash text NOT NULL,
    salt varchar(120),
    migrated_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_legacy_credential PRIMARY KEY (id),
    CONSTRAINT uq_legacy_credential_1 UNIQUE (user_id),
    CONSTRAINT ck_legacy_credential_algorithm CHECK (algorithm IN ('md5', 'sha1', 'sha256', 'bcrypt', 'phpass'))
);
COMMENT ON TABLE iam.legacy_credential IS 'Password hash imported from a system being migrated; verified once at first login, then re-hashed into user_account.password_hash and marked migrated.';
COMMENT ON COLUMN iam.legacy_credential.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN iam.legacy_credential.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.legacy_credential.user_id IS 'Account the imported hash belongs to.';
COMMENT ON COLUMN iam.legacy_credential.algorithm IS 'Hash algorithm of the imported credential.';
COMMENT ON COLUMN iam.legacy_credential.password_hash IS 'Imported hash.';
COMMENT ON COLUMN iam.legacy_credential.salt IS 'Imported salt, when the algorithm needs one.';
COMMENT ON COLUMN iam.legacy_credential.migrated_at IS 'When the password was re-hashed into the modern scheme (NULL = still pending).';
COMMENT ON COLUMN iam.legacy_credential.created_at IS 'Row creation time.';
COMMENT ON COLUMN iam.legacy_credential.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN iam.legacy_credential.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN iam.legacy_credential.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN iam.legacy_credential.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN iam.legacy_credential.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';

ALTER TABLE iam.mfa_credential ADD CONSTRAINT fk_mfa_credential_user_id FOREIGN KEY (user_id, tenant_id) REFERENCES iam.user_account (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_mfa_credential_user_id ON iam.mfa_credential (user_id);
ALTER TABLE iam.legacy_credential ADD CONSTRAINT fk_legacy_credential_user_id FOREIGN KEY (user_id, tenant_id) REFERENCES iam.user_account (id, tenant_id) ON DELETE CASCADE;
CREATE UNIQUE INDEX uq_user_role_assignment ON iam.user_role (user_id, role_id, scope_type, scope_id) NULLS NOT DISTINCT WHERE deleted_at IS NULL;

-- === P1-13: transactional outbox / inbox ===

CREATE TABLE iam.outbox_event (
    id bigint GENERATED ALWAYS AS IDENTITY,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    aggregate_type varchar(80) NOT NULL,
    aggregate_id uuid NOT NULL,
    payload text NOT NULL,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    CONSTRAINT pk_iam_outbox_event PRIMARY KEY (id)
);
COMMENT ON TABLE iam.outbox_event IS 'Transactional outbox of the iam module: events written in the same transaction as the change, published to the bus by a relay, then pruned. Ordered by the identity column.';
COMMENT ON COLUMN iam.outbox_event.id IS 'Monotonic sequence; publish order.';
COMMENT ON COLUMN iam.outbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.outbox_event.event_type IS 'Event name (module.entity.verb).';
COMMENT ON COLUMN iam.outbox_event.aggregate_type IS 'Entity kind the event is about.';
COMMENT ON COLUMN iam.outbox_event.aggregate_id IS 'Entity id the event is about.';
COMMENT ON COLUMN iam.outbox_event.payload IS 'Serialised event (opaque message envelope).';
COMMENT ON COLUMN iam.outbox_event.occurred_at IS 'When the change committed.';
COMMENT ON COLUMN iam.outbox_event.published_at IS 'When the relay published it (NULL = pending).';
CREATE INDEX ix_iam_outbox_event_pending ON iam.outbox_event (id) WHERE published_at IS NULL;
CREATE TABLE iam.inbox_event (
    event_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    received_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz,
    processing_error text,
    CONSTRAINT pk_iam_inbox_event PRIMARY KEY (event_id)
);
COMMENT ON TABLE iam.inbox_event IS 'Inbox of the iam module: ids of consumed events, kept so redeliveries are processed exactly once.';
COMMENT ON COLUMN iam.inbox_event.event_id IS 'Global id of the consumed event.';
COMMENT ON COLUMN iam.inbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN iam.inbox_event.event_type IS 'Event name.';
COMMENT ON COLUMN iam.inbox_event.received_at IS 'First delivery time.';
COMMENT ON COLUMN iam.inbox_event.processed_at IS 'When handling committed (NULL = in flight).';
COMMENT ON COLUMN iam.inbox_event.processing_error IS 'Last handling error, if any.';

